//! `pins.h`: C macros for every pin, bus line and ADC input of the board.

use std::fmt::Write;

use super::model::{AdcInput, BoardBindings};
use super::render::comment_text;
use super::view::{buses, Bus};

/// The `pins.h` text.
pub fn pins_h(b: &BoardBindings) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "/* Generated by Fusible from board `{}` ({}). */",
        text(&b.board),
        text(&b.mcu.chip)
    );
    out.push_str("/* DO NOT EDIT MANUALLY. Changes will be overwritten on next build. */\n\n");
    out.push_str("#ifndef FUSIBLE_PINS_H\n#define FUSIBLE_PINS_H\n\n");
    out.push_str(
        "/* Pin numbers: GPIOn is n; STM32 PXn is port * 16 + n (PA0 = 0, PB3 = 19). */\n",
    );
    for pin in &b.mcu.pins {
        let _ = writeln!(
            out,
            "#define PIN_{} {}u /* {}, net {} */",
            pin.signal_name,
            pin.pin_number,
            text(&pin.pin_label),
            text(&pin.net_name)
        );
    }
    for bus in buses(b) {
        bus_macros(&mut out, &bus);
    }
    for input in &b.adc {
        adc_macros(&mut out, input);
    }
    out.push_str("\n#endif /* FUSIBLE_PINS_H */\n");
    out
}

fn text(s: &str) -> String {
    comment_text(s).replace("*/", "* /")
}

fn bus_macros(out: &mut String, bus: &Bus) {
    let _ = writeln!(out, "\n/* {} */", bus.name);
    if !bus.devices.is_empty() {
        let _ = writeln!(out, "/* devices: {} */", text(&bus.devices.join(", ")));
    }
    if let Some(n) = bus.instance {
        let _ = writeln!(out, "#define {}_INSTANCE {n}u", bus.name);
    }
    for (role, pin) in &bus.lines {
        let role = role.to_ascii_uppercase();
        let _ = writeln!(out, "#define {}_{role} PIN_{}", bus.name, pin.signal);
        if let Some(af) = pin.af {
            let _ = writeln!(out, "#define {}_{role}_AF {af}u", bus.name);
        }
    }
    for (i, (pin, _)) in bus.chip_selects.iter().enumerate() {
        let _ = writeln!(out, "#define {}_CS{i} PIN_{}", bus.name, pin.signal);
    }
}

fn adc_macros(out: &mut String, input: &AdcInput) {
    let name = &input.pin.signal;
    let _ = writeln!(out, "\n/* ADC input {} */", text(&input.pin.label));
    if let Some((adc, ch)) = input.channel {
        let _ = writeln!(
            out,
            "#define {name}_ADC {adc}u\n#define {name}_ADC_CHANNEL {ch}u"
        );
    }
    if let Some(divider) = input.divider {
        let ratio = divider.ratio();
        let _ = writeln!(out, "#define {name}_DIVIDER {ratio:.4}f");
    }
}
